     "summary": "很多人来找我做咨询，开口第一句话是：“杨老师，我最近情绪特别差，是不是我太脆弱了？”我通常会告诉他们：情绪本身没有错，错的是产生情绪的那套思维。心理学中有个著名的ABC理论。A是事件，B是你对事件的看法，C是结果（也就是你的情绪）。很多人以为，是A直接导致了C，因为那件事太糟了，所以我痛苦。<p class=\"ql-align-j...",
